// kubejs/startup_scripts/autogeneratedyabbadabbadoo/framework/item_types.js

StartupEvents.registry('item', event => {
  for (var mat of global.MATERIALS) {
    var setPath = 'mkwrc:item/sets/' + mat.set

    var itemFlags = mat.flags.filter(function(f) {
      return !global.MODIFIER_FLAGS.includes(f)
    })

    var isGem = mat.form === 'gem'
    var primaryForm = isGem ? 'Gem' : 'Ingot'
    var primaryId = isGem ? '_gem' : '_ingot'
    var primaryName = isGem ? mat.display : mat.display + ' Ingot'

    // DUST
    if (!mat.flags.includes('noDust')) {
      event.create(mat.id + '_dust')
        .displayName(mat.display + ' Dust')
        .texture('layer0', setPath + '/dust')
        .color(0, mat.color)
        .tag('c:dusts')
        .tag('c:dusts/' + mat.id)
    }

    // MATERIAL FORMS
    for (var i = 0; i < itemFlags.length; i++) {
      var flag = itemFlags[i]
      var f = global.FLAGS[flag]

      if (!f || flag === 'Block') continue

      if (flag === 'Ingot' && isGem) continue

      if (flag === 'Spool') {
        event.create(mat.id + '_wire_spool')
          .displayName(mat.display + ' Wire Spool')
          .texture('layer0', 'mkwrc:item/wire_spool_overlay')
          .texture('layer1', setPath + '/wire')
          .color(1, mat.color)
          .tag('c:wire_spools')
          .tag('c:wire_spools/' + mat.id)
        continue
      }

      event.create(mat.id + '_' + f.id)
        .displayName(mat.display + ' ' + f.display)
        .texture('layer0', setPath + '/' + f.id)
        .color(0, mat.color)
        .tag('c:' + f.id + 's')
        .tag('c:' + f.id + 's/' + mat.id)
    }

    // BASE INGOT/GEM FALLBACK
    if (!itemFlags.includes(primaryForm) && !mat.flags.includes('noIngot')) {
      event.create(mat.id + primaryId)
        .displayName(primaryName)
        .texture('layer0', setPath + '/' + (isGem ? 'gem' : 'ingot'))
        .color(0, mat.color)
        .tag('c:' + (isGem ? 'gems' : 'ingots'))
        .tag('c:' + (isGem ? 'gems' : 'ingots') + '/' + mat.id)
    }

    // HOT INGOT
    if (!isGem && itemFlags.includes('Ingot') &&
        !mat.flags.includes('noHot')) {
      event.create(mat.id + '_hot_ingot')
        .displayName('Hot ' + mat.display + ' Ingot')
        .texture('layer0', setPath + '/ingot')
        .texture('layer1', setPath + '/hot_overlay')
        .color(0, mat.color)
        .tag('c:hot_ingots')
        .tag('c:hot_ingots/' + mat.id)
    }
  }
})